// Player controls: double-tap seek, toolbar, speed button, swipe -> native bridge (volume/brightness), PiP layout.
const { ENGINE, launch, run, check, canvasVideo } = require('./lib')
run('controls: gestures and toolbar over the site player', async () => {
  const browser = await launch()
  const ctx = await browser.newContext({ viewport: { width: 400, height: 800 }, hasTouch: true, isMobile: true })
  const page = await ctx.newPage()
  await page.route('https://test.local/', r => r.fulfill({ contentType: 'text/html', body: '<meta name=viewport content="width=device-width"><body style="margin:0"><video id=v playsinline style="width:400px;height:225px;display:block;margin-top:100px"></video></body>' }))
  await page.addInitScript(() => { window.__minCfg0 = { gestures: true } })
  await page.addInitScript(() => { window.__calls = []; window.AIBNative = { playing: (a, w, h) => window.__calls.push(['playing', a, w, h]), brightness: d => { window.__calls.push(['b', d]); return 0.5 }, volume: d => { window.__calls.push(['v', d]); return 0.6 }, pip: () => window.__calls.push(['pip']), position () {} } })
  await page.goto('https://test.local/')
  await page.evaluate(canvasVideo, 'v')
  await page.addScriptTag({ content: ENGINE })
  await page.waitForFunction(() => document.getElementById('v').readyState >= 2)
  await page.evaluate(() => { const v = document.getElementById('v'); let t = 20; window.__seeks = []; Object.defineProperty(v, 'currentTime', { get: () => t, set: x => { window.__seeks.push(x); t = x } }); Object.defineProperty(v, 'duration', { get: () => 3600 }); let pr = 1; window.__rates = []; Object.defineProperty(v, 'playbackRate', { get: () => pr, set: x => { window.__rates.push(x); pr = x } }) })
  await page.waitForTimeout(300)
  await page.touchscreen.tap(350, 210); await page.waitForTimeout(120); await page.touchscreen.tap(350, 210)
  await page.waitForTimeout(300)
  const t1 = await page.evaluate(() => document.getElementById('v').currentTime)
  check('double tap on the right: +10 s', t1 === 30, t1)
  await page.touchscreen.tap(40, 210); await page.waitForTimeout(120); await page.touchscreen.tap(40, 210)
  await page.waitForTimeout(300)
  const t2 = await page.evaluate(() => document.getElementById('v').currentTime)
  check('double tap on the left: -10 s', t2 === 20, t2)
  await page.waitForTimeout(600)
  const bar = await page.evaluate(() => { const c = document.querySelector('[data-aib-ctl]'); return c && { display: c.style.display, buttons: Array.from(c.children).filter(b => b.style.display !== 'none').map(b => b.textContent) } })
  check('toolbar shown after a touch (fullscreen, PiP, speed)', bar && bar.display === 'flex' && bar.buttons.length >= 3, bar)
  await page.click('[data-aib-ctl] > div:nth-child(3)'); await page.waitForTimeout(100)
  const rate = await page.evaluate(() => ({ set: window.__rates, label: document.querySelector('[data-aib-ctl] > div:nth-child(3)').textContent }))
  check('speed button: 1x -> 1.25x', rate.set.includes(1.25) && rate.label === '1.25×', rate)
  await page.waitForTimeout(1800)
  const rep = await page.evaluate(() => window.__calls.find(c => c[0] === 'playing'))
  check('app told that a video plays (with its size)', !!rep && rep[1] === true && rep[2] === 160 && rep[3] === 90, rep)
  // swipes need a full-screen video
  await page.evaluate(() => { document.getElementById('v').style.cssText = 'position:fixed;inset:0;width:100vw;height:100vh' })
  const cdp = await ctx.newCDPSession(page)
  const touch = async (type, x, y) => cdp.send('Input.dispatchTouchEvent', { type, touchPoints: type === 'touchEnd' ? [] : [{ x, y }] })
  await touch('touchStart', 300, 600); for (let y = 590; y >= 300; y -= 20) await touch('touchMove', 300, y); await touch('touchEnd')
  await touch('touchStart', 80, 600); for (let y = 590; y >= 400; y -= 20) await touch('touchMove', 80, y); await touch('touchEnd')
  const c = await page.evaluate(() => ({ volume: window.__calls.filter(x => x[0] === 'v').length, brightness: window.__calls.filter(x => x[0] === 'b').length }))
  check('swipe up on the right = volume, on the left = brightness', c.volume > 0 && c.brightness > 0, c)
  await page.evaluate(() => { document.getElementById('v').style.cssText = 'width:400px;height:225px;display:block;margin-top:100px' })
  await page.evaluate(() => window.__aibPip(true))
  const pip = await page.evaluate(() => { const r = document.getElementById('v').getBoundingClientRect(); return [r.width, r.height] })
  check('picture-in-picture: the video fills the page', pip[0] === 400 && pip[1] === 800, pip)
  await page.evaluate(() => window.__aibPip(false))
  const back = await page.evaluate(() => { const r = document.getElementById('v').getBoundingClientRect(); return [r.width, r.height] })
  check('leaving picture-in-picture restores the page layout', back[0] === 400 && back[1] === 225, back)
  await browser.close()
})
